import type { BankQuestion } from "@/lib/bank";

/** The Mughal Empire (History): 110 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"history-mughal-1","question":"Who founded the Mughal Empire in India?","options":["Akbar","Babur","Humayun","Aurangzeb"],"answer":1,"explanation":"Babur founded the Mughal Empire after the First Battle of Panipat in 1526.","difficulty":"easy"},
  {"id":"history-mughal-2","question":"The Taj Mahal was built by:","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":2,"explanation":"Shah Jahan built it in Agra in memory of his wife Mumtaz Mahal.","difficulty":"easy"},
  {"id":"history-mughal-3","question":"The Battle of Haldighati (1576) was fought between the Mughal army and:","options":["Shivaji","Rana Sanga","Maharana Pratap","Hemu"],"answer":2,"explanation":"Akbar’s forces, led by Man Singh, fought Maharana Pratap of Mewar.","difficulty":"moderate"},
  {"id":"history-mughal-4","question":"Which Mughal emperor built Fatehpur Sikri?","options":["Babur","Humayun","Akbar","Shah Jahan"],"answer":2,"explanation":"Akbar built Fatehpur Sikri as his capital.","difficulty":"moderate"},
  {"id":"history-mughal-5","question":"Din-i-Ilahi was started by:","options":["Babur","Akbar","Jahangir","Shah Jahan"],"answer":1,"explanation":"Akbar propounded Din-i-Ilahi in 1582 as a blend of ideas from several religions.","difficulty":"moderate"},
  {"id":"history-mughal-6","question":"The Second Battle of Panipat (1556) was fought between Akbar’s forces and:","options":["Ibrahim Lodi","Hemu","Rana Sanga","Sher Shah Suri"],"answer":1,"explanation":"Bairam Khan, leading Akbar’s army, defeated Hemu (Hem Chandra Vikramaditya).","difficulty":"hard"},
  {"id":"history-mughal-7","question":"Who defeated Humayun and forced him into exile?","options":["Hemu","Sher Shah Suri","Rana Sanga","Bairam Khan"],"answer":1,"explanation":"Sher Shah Suri defeated Humayun at Chausa (1539) and Kannauj (1540).","difficulty":"hard"},
  {"id":"history-mughal-8","question":"Who was Akbar’s regent during the early years of his reign?","options":["Abul Fazl","Bairam Khan","Todar Mal","Birbal"],"answer":1,"explanation":"Bairam Khan acted as regent from 1556 to 1560.","difficulty":"hard"},
  {"id":"history-mughal-9","question":"The Mansabdari system was introduced by:","options":["Babur","Akbar","Jahangir","Aurangzeb"],"answer":1,"explanation":"Akbar introduced the Mansabdari system to organise the nobility and army by ranks (mansabs).","difficulty":"very-hard"},
  {"id":"history-mughal-10","question":"The Battle of Khanwa (1527) was fought between Babur and:","options":["Ibrahim Lodi","Rana Sanga","Hemu","Medini Rai"],"answer":1,"explanation":"Babur defeated Rana Sanga of Mewar at Khanwa, near Agra, in 1527.","difficulty":"very-hard"},
  {"id":"history-mughal-11","question":"Which Mughal emperor reimposed the jizya tax in 1679?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":3,"explanation":"Akbar had abolished jizya in 1564; Aurangzeb reimposed it in 1679.","difficulty":"very-hard"},
  {"id":"history-mughal-12","question":"The First Battle of Panipat (1526) was fought between Babur and:","options":["Rana Sanga","Ibrahim Lodi","Hemu","Sher Shah"],"answer":1,"explanation":"Babur defeated Ibrahim Lodi and founded the Mughal Empire.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"history-mughal-13","question":"Din-i-Ilahi, a syncretic faith, was propounded by:","options":["Babur","Akbar","Jahangir","Shah Jahan"],"answer":1,"explanation":"Akbar announced Din-i-Ilahi in 1582.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"history-mughal-14","question":"The Battle of Haldighati (1576) was fought between Akbar’s forces and:","options":["Rana Sanga","Rana Pratap","Rana Kumbha","Rana Udai Singh"],"answer":1,"explanation":"Man Singh led the Mughal army against Maharana Pratap of Mewar.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"history-mughal-15","question":"Which Mughal ruler’s reign is called the “Golden Age of Mughal architecture”, with the Taj Mahal and Red Fort built?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":2,"explanation":"Shah Jahan (1628–58) built the Taj Mahal, Red Fort and Jama Masjid.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"history-mughal-16","question":"Which Mughal emperor re-imposed the jizya tax on non-Muslims in 1679?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":3,"explanation":"Akbar abolished jizya in 1564; Aurangzeb brought it back.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"history-mughal-17","question":"The Mughal emperor who was a prisoner of the Marathas and later of the British, and in whose reign the Battle of Buxar (1764) took place, was:","options":["Farrukhsiyar","Muhammad Shah","Shah Alam II","Bahadur Shah Zafar"],"answer":2,"explanation":"Shah Alam II fought at Buxar and granted the Diwani of Bengal to the Company in 1765.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-mughal-18","question":"The Second Battle of Panipat (1556) was fought between Akbar’s army, led by Bairam Khan, and:","options":["Ibrahim Lodi","Hemu","Sher Shah Suri","Rana Sanga"],"answer":1,"explanation":"Hemu was defeated and killed; Akbar’s rule was secured.","difficulty":"hard"},
  {"id":"history-mughal-19","question":"Babur’s memoir, the Baburnama, was originally written in:","options":["Persian","Arabic","Chagatai Turkish","Urdu"],"answer":2,"explanation":"Babur wrote in his mother tongue, Chagatai Turkish; it was translated into Persian under Akbar.","difficulty":"hard"},
  {"id":"history-mughal-20","question":"The Zabti (Dahsala) land revenue system under Akbar was developed by:","options":["Birbal","Raja Todar Mal","Abul Fazl","Man Singh"],"answer":1,"explanation":"Raja Todar Mal measured land and fixed revenue on the average produce of ten years.","difficulty":"very-hard"},
  {"id":"history-mughal-21","question":"Consider: 1. The Buland Darwaza at Fatehpur Sikri commemorates Akbar’s Gujarat campaign. 2. Akbar’s Ibadat Khana was at Fatehpur Sikri. 3. Akbar abolished the pilgrimage tax. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct; the pilgrimage tax went in 1563 and the jizya in 1564.","difficulty":"very-hard"},
  {"id":"history-mughal-22","question":"How many of these statements are correct? I. Sher Shah defeated Humayun at Chausa (1539) and Kannauj (1540). II. Sher Shah issued the silver coin called the rupiya. III. Sher Shah rebuilt and extended the road later called the Grand Trunk Road. IV. Humayun’s tomb was built by Shah Jahan.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Humayun’s tomb was built in Akbar’s reign, commissioned by Bega Begum.","difficulty":"very-hard"},
  {"id":"history-mughal-23","question":"How many of these statements are correct? I. The Peacock Throne was made for Shah Jahan. II. Nadir Shah carried it away in 1739. III. Aurangzeb died in 1707.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are correct.","difficulty":"very-hard"},
  {"id":"history-mughal-24","question":"Arrange in chronological order: 1. Second Battle of Panipat 2. Battle of Khanwa 3. Battle of Haldighati 4. Battle of Chausa","options":["2-4-1-3","4-2-1-3","2-1-4-3","2-4-3-1"],"answer":0,"explanation":"Khanwa (1527), Chausa (1539), Second Panipat (1556), Haldighati (1576).","difficulty":"very-hard"},
  {"id":"history-mughal-25","question":"How many of these statements are correct? I. Akbar’s Mahzar (1579) let him decide between conflicting interpretations of Islamic law. II. Din-i-Ilahi was propagated by Jahangir. III. Akbar abolished the jizya in 1564.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and III. Din-i-Ilahi was Akbar’s, started in 1582.","difficulty":"very-hard"},
  {"id":"history-mughal-26","question":"In the Mughal mansabdari system, the “sawar” rank showed:","options":["The officer’s personal rank and salary","The number of cavalrymen he had to maintain","The land revenue assigned to him","The number of elephants under his command"],"answer":1,"explanation":"Zat was the personal rank and salary; sawar was the number of horsemen the mansabdar had to keep.","difficulty":"very-hard"},
  {"id":"history-mughal-27","question":"Arrange in chronological order: 1. Treaty of Purandar between Shivaji and Jai Singh 2. Battle of Samugarh 3. Jahangir’s marriage to Nur Jahan 4. Start of construction of the Taj Mahal","options":["3-4-2-1","3-2-4-1","4-3-2-1","3-4-1-2"],"answer":0,"explanation":"Nur Jahan’s marriage (1611), Taj Mahal begun (1632), Samugarh (1658, where Aurangzeb defeated Dara Shikoh), Treaty of Purandar (1665).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-mughal-28","question":"How many of these statements are correct? I. Jahangir’s memoir is the Tuzuk-i-Jahangiri. II. The Ain-i-Akbari is the third volume of Abul Fazl’s Akbarnama. III. Aurangzeb took the title Alamgir. IV. The Red Fort of Delhi was built by Akbar.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Red Fort of Delhi was built by Shah Jahan when he moved the capital to Shahjahanabad; Akbar built the Agra fort.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-29", "question": "Humayun’s Tomb, the first great garden-tomb of the Mughals and a model for the Taj Mahal, stands in:", "options": ["Agra", "Delhi", "Lahore", "Fatehpur Sikri"], "answer": 1, "explanation": "The tomb in Delhi was commissioned by Humayun’s widow Bega Begum (Haji Begum) and completed around 1572; it is a UNESCO World Heritage Site.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-mughal-30", "question": "The original name of Jahangir’s empress Nur Jahan was:", "options": ["Mehr-un-Nisa", "Mumtaz Mahal", "Jahanara", "Arjumand Banu Begum"], "answer": 0, "explanation": "Mehr-un-Nisa, daughter of Mirza Ghiyas Beg (Itimad-ud-Daulah), married Jahangir in 1611 and was titled Nur Mahal and then Nur Jahan. Arjumand Banu was Mumtaz Mahal, her niece.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-mughal-31", "question": "Which Mughal emperor was called “Zinda Pir” (living saint) because of his austere, orthodox life?", "options": ["Akbar", "Shah Jahan", "Aurangzeb", "Bahadur Shah I"], "answer": 2, "explanation": "Aurangzeb copied the Quran, stitched caps for a living and banned court music, earning the epithet Zinda Pir from his orthodox admirers.", "difficulty": "easy", "source": "SSC CGL · UPSSSC PET"},
  {"id": "history-mughal-32", "question": "Who among the following was NOT one of the Navratnas (nine jewels) of Akbar’s court?", "options": ["Raja Todar Mal", "Abdur Rahim Khan-i-Khanan", "Bairam Khan", "Mullah Do-Piyaza"], "answer": 2, "explanation": "Bairam Khan was Akbar’s regent, dismissed in 1560 and killed on his way to Mecca, long before the Navratnas gathered. The nine were Abul Fazl, Faizi, Tansen, Birbal, Todar Mal, Man Singh, Abdur Rahim, Fakir Aziao-Din and Mullah Do-Piyaza.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-mughal-33", "question": "The Battle of Ghaghra (1529), the last major battle of Babur in India, was fought against:", "options": ["Rana Sanga", "The Afghans led by Mahmud Lodi", "Medini Rai of Chanderi", "Sher Khan Sur"], "answer": 1, "explanation": "Babur defeated the Afghan chiefs of Bihar and Bengal under Mahmud Lodi (brother of Ibrahim Lodi) on the Ghaghra. Rana Sanga was beaten at Khanwa (1527) and Medini Rai at Chanderi (1528).", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-34", "question": "The “Chain of Justice” (zanjir-i-adl), a golden chain with bells that any petitioner could pull, was set up by:", "options": ["Akbar", "Jahangir", "Shah Jahan", "Sher Shah"], "answer": 1, "explanation": "Jahangir hung the chain between the Shah Burj of Agra fort and a post on the river bank so that aggrieved subjects could reach the emperor directly; it is described in his memoir.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "history-mughal-35", "question": "After the war of succession, Shah Jahan was imprisoned by Aurangzeb for the last eight years of his life in:", "options": ["Red Fort, Delhi", "Agra Fort", "Gwalior Fort", "Lahore Fort"], "answer": 1, "explanation": "Shah Jahan was confined in Agra Fort from 1658 until his death in 1666, cared for by his daughter Jahanara, within sight of the Taj Mahal.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-mughal-36", "question": "Sir Thomas Roe, ambassador of King James I of England, visited the court of:", "options": ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], "answer": 1, "explanation": "Roe stayed at Jahangir’s court from 1615 to 1619 and obtained trading concessions for the East India Company; William Hawkins had visited earlier (1608–11).", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-37", "question": "In the Battle of Chanderi (1528), Babur defeated the Rajput chief:", "options": ["Rana Sanga", "Medini Rai", "Hasan Khan Mewati", "Rana Udai Singh"], "answer": 1, "explanation": "Medini Rai, an ally of Rana Sanga, held Chanderi in Malwa; its capture in January 1528 secured Babur’s hold over central India. Hasan Khan Mewati fought at Khanwa.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "history-mughal-38", "question": "Humayun recovered Delhi in 1555 after his forces defeated which Sur ruler at the Battle of Sirhind?", "options": ["Islam Shah Sur", "Sikandar Shah Sur", "Adil Shah Sur", "Sher Shah Sur"], "answer": 1, "explanation": "Bairam Khan led Humayun’s army to victory over Sikandar Shah Sur at Sirhind in June 1555, ending the Sur interregnum; Humayun died in January 1556 after a fall from his library stairs.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-39", "question": "Akbar’s first matrimonial alliance with a Rajput house (1562) was with the daughter of Raja Bharmal of:", "options": ["Marwar", "Mewar", "Amber", "Bikaner"], "answer": 2, "explanation": "Harkha Bai (popularly Jodha Bai), daughter of Bharmal of Amber (Jaipur), married Akbar in 1562 and became the mother of Jahangir; Mewar under Rana Pratap never submitted.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-40", "question": "Aurangzeb annexed the Deccan sultanates of Bijapur and Golconda respectively in:", "options": ["1636 and 1656", "1686 and 1687", "1681 and 1689", "1676 and 1686"], "answer": 1, "explanation": "Bijapur fell in 1686 and Golconda in 1687, after which Aurangzeb spent the rest of his reign fighting the Marathas in the Deccan.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-41", "question": "Which Mughal emperor drove the Portuguese out of their settlement at Hugli in Bengal in 1632?", "options": ["Jahangir", "Shah Jahan", "Aurangzeb", "Akbar"], "answer": 1, "explanation": "Shah Jahan ordered the siege of Hugli because of Portuguese piracy and slave-trading; the settlement was sacked and many Portuguese taken prisoner.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-mughal-42", "question": "Guru Arjan Dev, the fifth Sikh Guru, was executed in 1606 during the reign of:", "options": ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], "answer": 1, "explanation": "Jahangir had Guru Arjan executed for allegedly helping the rebel prince Khusrau. Guru Tegh Bahadur was executed in 1675 under Aurangzeb.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-43", "question": "The “Padshahnama”, the official history of Shah Jahan’s reign, was written by:", "options": ["Abdul Hamid Lahori", "Abul Fazl", "Khafi Khan", "Mutamid Khan"], "answer": 0, "explanation": "Abdul Hamid Lahori wrote the Padshahnama; Khafi Khan wrote the Muntakhab-ul-Lubab on Aurangzeb’s reign and Mutamid Khan the Iqbalnama-i-Jahangiri.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-mughal-44", "question": "Akbar’s Dahsala system, which fixed revenue on the basis of the average produce and prices of the previous ten years, was introduced in:", "options": ["1560", "1571", "1580", "1596"], "answer": 2, "explanation": "Todar Mal introduced the Dahsala (Ain-i-Dahsala) in 1580, the 24th year of Akbar’s reign, after the earlier experiments with karori officers (1574).", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-45", "question": "At the First Battle of Panipat, Babur’s artillery was commanded by:", "options": ["Ustad Ali Quli and Mustafa Rumi", "Bairam Khan and Tardi Beg", "Humayun and Askari", "Mir Baqi and Zahid Beg"], "answer": 0, "explanation": "The Ottoman-trained gunners Ustad Ali Quli and Mustafa Rumi managed Babur’s cannon, used with the Tulughma flanking tactic and the Rumi (Ottoman) device of chained carts.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-mughal-46", "question": "The “Fatawa-i-Alamgiri”, a digest of Islamic law, was compiled under the orders of:", "options": ["Akbar", "Shah Jahan", "Aurangzeb", "Jahangir"], "answer": 2, "explanation": "Aurangzeb (Alamgir) had a body of scholars compile the Fatawa-i-Alamgiri as the authoritative code of Hanafi law for his empire.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-47", "question": "Arrange in chronological order: 1. Battle of Sirhind 2. Battle of Ghaghra 3. Battle of Kannauj (Bilgram) 4. Battle of Samugarh", "options": ["2, 3, 1, 4", "2, 1, 3, 4", "3, 2, 1, 4", "2, 3, 4, 1"], "answer": 0, "explanation": "Ghaghra (1529), Kannauj (1540, Sher Shah defeats Humayun), Sirhind (1555, Humayun returns) and Samugarh (1658, Aurangzeb defeats Dara Shikoh).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-48", "question": "How many of these statements about Akbar are correct? I. He was born at Amarkot in 1542. II. He was crowned at Kalanaur in 1556. III. He captured Chittor in 1568 and Ranthambore in 1569. IV. He built Humayun’s Tomb in Delhi.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Humayun’s Tomb was commissioned by Humayun’s widow Bega Begum, not by Akbar.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-49", "question": "Which pair of Mughal-period work and its author is NOT correctly matched?", "options": ["Akbarnama – Abul Fazl", "Tabaqat-i-Akbari – Nizamuddin Ahmad", "Muntakhab-ut-Tawarikh – Abdul Qadir Badauni", "Humayun-nama – Abul Fazl"], "answer": 3, "explanation": "The Humayun-nama was written by Gulbadan Begum, Babur’s daughter and Humayun’s sister, at Akbar’s request.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-50", "question": "Assertion (A): Mughal painting reached its peak in the reign of Jahangir. Reason (R): Jahangir was a connoisseur who patronised masters like Mansur and Abul Hasan and claimed he could identify the hand of each artist in a composite picture.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Jahangir’s personal patronage and his taste for portraiture and natural-history painting (Mansur’s birds and animals) explain why his reign is seen as the climax of Mughal painting.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-51", "question": "How many of these statements about Aurangzeb are correct? I. He banned music at the court. II. He had the Maratha king Sambhaji executed in 1689. III. He died at Ahmednagar in 1707. IV. The Peacock Throne was carried away from Delhi during his reign.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Nadir Shah carried off the Peacock Throne in 1739, in the reign of Muhammad Shah.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-52", "question": "How many of these statements about the mansabdari system are correct? I. The zat rank fixed the personal status and salary of the mansabdar. II. Mansabdars were paid either in cash or through a jagir. III. The du-aspah sih-aspah rank was introduced by Jahangir. IV. The dagh (branding of horses) system was enforced by Akbar.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Du-aspah sih-aspah let a mansabdar maintain double the number of troopers for the same sawar rank; dagh prevented fraud in the muster of horses.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-53", "question": "Arrange in chronological order: 1. Third Battle of Panipat 2. Battle of Buxar 3. Nadir Shah’s sack of Delhi 4. Death of Aurangzeb", "options": ["4, 3, 1, 2", "4, 1, 3, 2", "3, 4, 1, 2", "4, 3, 2, 1"], "answer": 0, "explanation": "Aurangzeb’s death (1707), Nadir Shah’s invasion (1739), Third Battle of Panipat (1761) and Buxar (1764).", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-54", "question": "Which pair of Mughal monument and its builder is NOT correctly matched?", "options": ["Buland Darwaza – Akbar", "Tomb of Itimad-ud-Daulah – Nur Jahan", "Bibi ka Maqbara – Azam Shah, son of Aurangzeb", "Jama Masjid, Delhi – Aurangzeb"], "answer": 3, "explanation": "The Jama Masjid of Delhi (1656) was built by Shah Jahan. Bibi ka Maqbara at Aurangabad, a copy of the Taj, was built by Azam Shah for his mother.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-55", "question": "How many of these statements about Sher Shah Suri are correct? I. His original name was Farid Khan. II. He built the Qila-i-Kuhna mosque inside the Purana Qila at Delhi. III. He died in 1545 during the siege of Kalinjar. IV. He introduced the patta and qabuliyat documents in land revenue.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Sher Shah was killed by a gunpowder explosion at Kalinjar; his revenue practices were later adopted by Akbar.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-56", "question": "Assertion (A): Babur’s victory at Panipat in 1526 did not immediately make him the master of Hindustan. Reason (R): The Rajput confederacy under Rana Sanga and the Afghan chiefs in the east still challenged him, forcing the battles of Khanwa and Ghaghra.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Panipat only removed Ibrahim Lodi; Khanwa (1527) broke Rajput power and Ghaghra (1529) the Afghan resistance, securing Babur’s rule.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-57", "question": "How many of these statements about the later Mughals are correct? I. Bahadur Shah I succeeded Aurangzeb. II. Farrukhsiyar issued the farman of 1717 granting trade privileges to the East India Company in Bengal. III. Muhammad Shah “Rangeela” was the emperor when Nadir Shah invaded India. IV. Bahadur Shah Zafar was exiled to Rangoon after the revolt of 1857.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The 1717 farman has been called the Magna Carta of the Company; Bahadur Shah Zafar died in Rangoon in 1862.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-58", "question": "Which pair of 18th-century noble and the state he founded is NOT correctly matched?", "options": ["Chin Qilich Khan (Nizam-ul-Mulk) – Hyderabad", "Saadat Khan – Awadh", "Murshid Quli Khan – Awadh", "Sayyid brothers – known as king-makers at Delhi"], "answer": 2, "explanation": "Murshid Quli Khan made Bengal virtually independent (capital Murshidabad); Awadh was founded by Saadat Khan Burhan-ul-Mulk in 1722 and Hyderabad by Nizam-ul-Mulk in 1724.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "history-mughal-59", "question": "The tomb of Akbar is located at:", "options": ["Fatehpur Sikri", "Sikandra, near Agra", "Lahore", "Delhi"], "answer": 1, "explanation": "Akbar’s tomb is at Sikandra near Agra; Akbar began it and Jahangir completed it. Jahangir’s own tomb is at Shahdara, Lahore.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-60", "question": "Which Mughal emperor died in 1556 after falling down the stairs of his library, the Sher Mandal, in Delhi?", "options": ["Babur", "Akbar", "Humayun", "Jahangir"], "answer": 2, "explanation": "Humayun fell from the steps of the Sher Mandal in the Purana Qila a few months after regaining Delhi, and 13-year-old Akbar succeeded him.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-61", "question": "Babur was descended from:", "options": ["Timur on his father’s side and Genghis Khan on his mother’s side", "Genghis Khan on his father’s side and Timur on his mother’s side", "The Lodi Afghans", "The Safavid rulers of Persia"], "answer": 0, "explanation": "Babur was a Timurid through his father, Umar Shaikh Mirza, and descended from Genghis Khan through his mother, a Chagatai princess.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-62", "question": "Before his accession, Jahangir was known as:", "options": ["Khurram", "Murad", "Daniyal", "Salim"], "answer": 3, "explanation": "Akbar named his son Salim after the Sufi saint Shaikh Salim Chishti of Sikri. Khurram was Shah Jahan’s name before accession.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-63", "question": "The Shalimar Bagh at Srinagar was laid out by:", "options": ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], "answer": 1, "explanation": "Jahangir laid out the Shalimar Bagh in Srinagar for Nur Jahan. The Shalimar Bagh of Lahore was built later by Shah Jahan.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-64", "question": "The tomb of Sher Shah Suri, set in the middle of an artificial lake, is at:", "options": ["Sasaram, Bihar", "Delhi", "Jaunpur", "Agra"], "answer": 0, "explanation": "Sher Shah’s tomb at Sasaram, his birthplace region in Bihar, is a fine example of Indo-Afghan architecture.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-65", "question": "The Bibi Ka Maqbara at Aurangabad, modelled on the Taj Mahal, was built in memory of Aurangzeb’s wife Dilras Banu Begum by:", "options": ["Aurangzeb himself", "Bahadur Shah I", "Azam Shah", "Kam Bakhsh"], "answer": 2, "explanation": "Prince Azam Shah built it for his mother, Dilras Banu Begum, around 1660–61. It is often called the “Taj of the Deccan”.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "history-mughal-66", "question": "Akbar built the Ibadat Khana (House of Worship) at Fatehpur Sikri in:", "options": ["1562", "1575", "1582", "1569"], "answer": 1, "explanation": "The Ibadat Khana was built in 1575; at first only Muslim scholars debated there, but from 1578 it was opened to Hindus, Jains, Zoroastrians and Christians.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-67", "question": "The “Muntakhab-ut-Tawarikh”, a history highly critical of Akbar’s religious policy, was written by:", "options": ["Abul Fazl", "Nizamuddin Ahmad", "Faizi", "Abdul Qadir Badauni"], "answer": 3, "explanation": "Badauni, an orthodox scholar at Akbar’s court, wrote it privately. Abul Fazl wrote the official Akbarnama and Nizamuddin the Tabaqat-i-Akbari.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-68", "question": "Aurangzeb was buried in a simple open-air grave at:", "options": ["Ahmednagar", "Delhi", "Khuldabad, near Aurangabad", "Burhanpur"], "answer": 2, "explanation": "Aurangzeb died at Ahmednagar in 1707 but was buried, as he wished, in an unadorned grave at Khuldabad near the shrine of Shaikh Zainuddin.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-mughal-69", "question": "In 1580 Akbar divided his empire into how many subas (provinces)?", "options": ["8", "12", "15", "21"], "answer": 1, "explanation": "Akbar created 12 subas in 1580; the conquest of the Deccan raised the number to 15 by the end of his reign.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-70", "question": "Guru Tegh Bahadur, the ninth Sikh Guru, was executed in Delhi in 1675 on the orders of:", "options": ["Jahangir", "Shah Jahan", "Bahadur Shah I", "Aurangzeb"], "answer": 3, "explanation": "Guru Tegh Bahadur was beheaded at Chandni Chowk (now Gurdwara Sis Ganj) in 1675 under Aurangzeb. Guru Arjan Dev was executed under Jahangir in 1606.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-71", "question": "The standard copper coin of the Mughal currency system was the:", "options": ["Mohur", "Dam", "Rupiya", "Tanka"], "answer": 1, "explanation": "The Mughal system had the gold mohur, the silver rupiya and the copper dam; 40 dams made a rupee in Akbar’s time. The tanka belonged to the Delhi Sultanate.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-mughal-72", "question": "The illustrated Hamzanama, one of the earliest major projects of Akbar’s painting workshop, was supervised by the Persian masters:", "options": ["Mansur and Abul Hasan", "Bishandas and Manohar", "Mir Sayyid Ali and Abd al-Samad", "Daswanth and Basawan"], "answer": 2, "explanation": "Mir Sayyid Ali and Abd al-Samad, brought from Persia by Humayun, led the Hamzanama project. Mansur and Abul Hasan flourished under Jahangir; Daswanth and Basawan were Indian painters of Akbar’s atelier.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-73", "question": "Arrange these battles of the Mughal war of succession in chronological order: 1. Deorai 2. Samugarh 3. Dharmat 4. Khajwa", "options": ["3, 2, 1, 4", "2, 3, 4, 1", "3, 4, 2, 1", "3, 2, 4, 1"], "answer": 3, "explanation": "Dharmat (April 1658, over Jaswant Singh), Samugarh (May 1658, over Dara Shukoh), Khajwa (January 1659, over Shuja), Deorai (March 1659, Dara’s final defeat).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-74", "question": "Match the monument with its builder: A. Red sandstone Agra Fort B. Tomb of Itimad-ud-Daulah, Agra C. Badshahi Mosque, Lahore D. Jama Masjid, Delhi. 1. Shah Jahan 2. Aurangzeb 3. Nur Jahan 4. Akbar", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-1, B-3, C-2, D-4", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Akbar rebuilt the Agra Fort in red sandstone; Nur Jahan built her father’s marble tomb with pietra dura; Aurangzeb built the Badshahi Mosque (1673); Shah Jahan built the Jama Masjid of Delhi.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-75", "question": "Assertion (A): Aurangzeb’s Deccan wars badly strained Mughal finances. Reason (R): Aurangzeb spent the last quarter-century of his reign, from 1681 to 1707, campaigning in the Deccan.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. The prolonged campaigns against Bijapur, Golconda and the Marathas drained the treasury and weakened control in the north.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-76", "question": "How many of these statements about Akbar’s religious policy are correct? I. His policy of Sulh-i-kul meant universal peace among faiths. II. The Ibadat Khana debates were thrown open to non-Muslims from 1578. III. Jesuit missions from Goa visited his court. IV. He issued the Mahzar in 1579.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Jesuit missions came from 1580 onward; the Mahzar (1579) made Akbar the arbiter in disputes over Islamic law.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-77", "question": "Match the Persian translation with the original work: A. Razmnama B. Translation by Badauni at Akbar’s order C. Sirr-i-Akbar D. Translation by Faizi. 1. Upanishads 2. Lilavati 3. Mahabharata 4. Ramayana", "options": ["A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1"], "answer": 1, "explanation": "The Razmnama is the Persian Mahabharata; Badauni translated the Ramayana; Dara Shukoh’s Sirr-i-Akbar (1657) rendered fifty Upanishads; Faizi translated Bhaskara’s mathematical work Lilavati.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-78", "question": "Arrange in chronological order: 1. William Hawkins at Jahangir’s court 2. Sir Thomas Roe at Jahangir’s court 3. Farrukhsiyar’s farman to the English 4. Shah Jahan expels the Portuguese from Hugli", "options": ["1, 2, 3, 4", "2, 1, 4, 3", "1, 4, 2, 3", "1, 2, 4, 3"], "answer": 3, "explanation": "Hawkins: 1609. Roe: 1615–19. Hugli captured from the Portuguese: 1632. Farrukhsiyar’s farman: 1717.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-79", "question": "How many of these statements about Babur are correct? I. He became ruler of Ferghana as a boy of about twelve. II. He used the tulughma tactic at the First Battle of Panipat. III. He took the title Padshah in 1507. IV. He was finally buried at Kabul.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Babur was first buried at Agra and later reburied in the Bagh-e Babur at Kabul, as he had wished.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "history-mughal-80", "question": "Which of these was NOT built by Shah Jahan?", "options": ["Jama Masjid, Delhi", "Moti Masjid in the Agra Fort", "Shalimar Bagh, Lahore", "Buland Darwaza, Fatehpur Sikri"], "answer": 3, "explanation": "Akbar built the Buland Darwaza (c. 1575) to mark his Gujarat victory. Shah Jahan built the Jama Masjid, the Agra Fort Moti Masjid and the Shalimar gardens at Lahore.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-81", "question": "How many of these officials of Mughal central administration are correctly matched with their charge? I. Diwan – revenue and finance II. Mir Bakhshi – military administration and the mansabdars III. Sadr-us-sudur – religious endowments and charity IV. Muhtasib – command of the imperial army", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: the muhtasib was the censor of public morals, enforcing Islamic conduct; the Mir Saman looked after the imperial household and karkhanas.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-82", "question": "Arrange these events of Akbar’s reign in chronological order: 1. Conquest of Gujarat 2. Battle of Haldighati 3. Capture of Asirgarh 4. Introduction of the Dahsala system", "options": ["1, 2, 4, 3", "2, 1, 4, 3", "1, 4, 2, 3", "1, 2, 3, 4"], "answer": 0, "explanation": "Gujarat conquered 1572–73; Haldighati 1576; Dahsala system 1580; Asirgarh, Akbar’s last conquest, 1601.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-83", "question": "How many of these statements about Shah Jahan are correct? I. He founded the city of Shahjahanabad in Delhi. II. The Peacock Throne was made for him. III. The title Shah Jahan was conferred on Prince Khurram by Jahangir after his Deccan campaign. IV. He died at Lahore.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: Shah Jahan died in 1666 in the Agra Fort, where Aurangzeb had confined him.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-84", "question": "The standard gold coin of the Mughal currency system was the:", "options": ["Dam", "Mohur", "Rupiya", "Jital"], "answer": 1, "explanation": "The gold mohur, the silver rupiya and the copper dam made up the Mughal currency. The jital was a coin of the Delhi Sultanate.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-85", "question": "Which Mughal emperor issued coins showing the signs of the zodiac?", "options": ["Akbar", "Shah Jahan", "Aurangzeb", "Jahangir"], "answer": 3, "explanation": "Jahangir's zodiac coins, each showing the sign of a month, are famous for their artistry. He also issued coins bearing Nur Jahan's name.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-86", "question": "Mumtaz Mahal, in whose memory the Taj Mahal was built, died in 1631 at:", "options": ["Agra", "Burhanpur", "Lahore", "Delhi"], "answer": 1, "explanation": "She died in childbirth at Burhanpur in the Deccan while with Shah Jahan on campaign. Her body was later moved to Agra, where the Taj Mahal was built.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "history-mughal-87", "question": "Rani Durgavati, who died fighting the Mughals in 1564, ruled the kingdom of:", "options": ["Gondwana (Garha-Katanga)", "Malwa", "Mewar", "Khandesh"], "answer": 0, "explanation": "Durgavati, the regent of Garha-Katanga (Gondwana), fought Akbar's general Asaf Khan and killed herself rather than be captured. Malwa had been taken from Baz Bahadur in 1561.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-88", "question": "The architect chiefly credited with the design of the Taj Mahal is:", "options": ["Mirak Mirza Ghiyas", "Abdul Hamid Lahori", "Ustad Mansur", "Ustad Ahmad Lahori"], "answer": 3, "explanation": "Ustad Ahmad Lahori is usually named as the chief architect of the Taj Mahal, and he also worked on the Red Fort at Delhi. Mirak Mirza Ghiyas designed Humayun's Tomb, and Abdul Hamid Lahori was a historian.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-89", "question": "The period 1560–62 of Akbar's reign, when his foster-mother and her relatives dominated the court, is often called the \"petticoat government\". The foster-mother was:", "options": ["Hamida Banu Begum", "Gulbadan Begum", "Maham Anaga", "Salima Sultan Begum"], "answer": 2, "explanation": "Maham Anaga and her son Adham Khan had great influence after Bairam Khan fell. Adham Khan killed the minister Atga Khan in 1562, and Akbar had him thrown from the palace terrace, which ended the phase.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-90", "question": "The ruler of Malwa, remembered for his romance with Rupmati, who was defeated by Akbar's forces in 1561, was:", "options": ["Daud Khan", "Baz Bahadur", "Yusuf Shah Chak", "Muzaffar Shah III"], "answer": 1, "explanation": "Baz Bahadur lost Malwa to Adham Khan in 1561. Daud Khan Karrani ruled Bengal, Yusuf Shah Chak Kashmir, and Muzaffar Shah III Gujarat.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-91", "question": "Under the Mughals, the head of a province (suba) was the:", "options": ["Subedar", "Faujdar", "Amil", "Kotwal"], "answer": 0, "explanation": "The subedar (also called sipahsalar or nazim) headed the suba. A diwan in each province handled revenue and reported to the central diwan, which kept a check on the subedar.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-92", "question": "Abul Fazl was murdered in 1602 by Bir Singh Bundela at the instigation of:", "options": ["Prince Daniyal", "Prince Murad", "Prince Khusrau", "Prince Salim"], "answer": 3, "explanation": "Prince Salim, the future Jahangir, was in revolt and saw Abul Fazl as his enemy, so he had Bir Singh Deo Bundela ambush him on his way back from the Deccan. Bir Singh later rose high under Jahangir.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-93", "question": "Birbal, one of Akbar's best-known courtiers, was killed in 1586 while fighting:", "options": ["The Rajputs of Mewar", "The Yusufzai Afghans on the north-west frontier", "The Ahoms of Assam", "The Deccan sultanates"], "answer": 1, "explanation": "Birbal died in an ambush in the Swat region during the campaign against the Yusufzai tribesmen, and Akbar is said to have mourned him deeply.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-94", "question": "Daud Khan Karrani, the Afghan ruler of Bengal, was defeated and killed by Akbar's forces in 1576 at the Battle of:", "options": ["Tukaroi", "Sarnal", "Rajmahal", "Chausa"], "answer": 2, "explanation": "His defeat at Rajmahal (July 1576) brought Bengal under the Mughals. Tukaroi (1575) was an earlier defeat for him, and Sarnal (1572) was fought in Akbar's Gujarat campaign.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-95", "question": "In 1626 a Mughal general seized Jahangir on the banks of the Jhelum in a coup against Nur Jahan's faction. The general was:", "options": ["Asaf Khan", "Mahabat Khan", "Khan-i-Khanan Abdur Rahim", "Ali Mardan Khan"], "answer": 1, "explanation": "Mahabat Khan held the emperor for some months before Nur Jahan's tactics freed him. Asaf Khan was Nur Jahan's brother and Shah Jahan's father-in-law.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-96", "question": "Shah Jahan's costly and unsuccessful campaign of 1646–47 in Central Asia, led by Princes Murad and Aurangzeb, was aimed at:", "options": ["Kandahar", "Kabul", "Herat", "Balkh and Badakhshan"], "answer": 3, "explanation": "Shah Jahan hoped to win back the Timurid homeland, but the Mughals had to withdraw from Balkh at great cost. The three failed sieges of Kandahar came later (1649–53).", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-97", "question": "The \"Alamgirnama\", the official history of the first ten years of Aurangzeb's reign, was written by:", "options": ["Khafi Khan", "Saqi Mustaid Khan", "Mirza Muhammad Kazim", "Abdul Hamid Lahori"], "answer": 2, "explanation": "Mirza Muhammad Kazim wrote the Alamgirnama, and Aurangzeb then stopped official history-writing. Saqi Mustaid Khan wrote the Maasir-i-Alamgiri after his death, and Khafi Khan wrote the Muntakhab-ul-Lubab privately.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-98", "question": "Shivaji escaped from Mughal custody at Agra in:", "options": ["1666", "1660", "1674", "1680"], "answer": 0, "explanation": "After the Treaty of Purandar (1665), Shivaji went to Aurangzeb's court in 1666, was kept under house arrest, and escaped in August 1666. He was crowned in 1674 and died in 1680.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-99", "question": "Which son of Aurangzeb rebelled in 1681 in alliance with the Rajputs and later took refuge with the Maratha king Sambhaji?", "options": ["Prince Muazzam", "Prince Akbar", "Prince Azam", "Prince Kam Bakhsh"], "answer": 1, "explanation": "Prince Akbar declared himself emperor in 1681 during the Rajput war. When his attempt failed he fled to Sambhaji and later to Persia, and this drew Aurangzeb into the Deccan for good.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-100", "question": "Humayun's Tomb in Delhi was designed by the Persian architect:", "options": ["Ustad Ahmad Lahori", "Ustad Isa", "Mir Abdul Karim", "Mirak Mirza Ghiyas"], "answer": 3, "explanation": "Mirak Mirza Ghiyas designed the tomb (built about 1565–72), which was commissioned after Humayun's death by his widow Bega Begum. It was the first great garden-tomb and a model for the Taj.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-101", "question": "Chand Bibi is remembered for defending which fort against the Mughals in 1595?", "options": ["Asirgarh", "Bijapur", "Ahmadnagar", "Golconda"], "answer": 2, "explanation": "Chand Bibi, regent of Ahmadnagar, held off Prince Murad's siege in 1595. She was killed in 1600, after which the Mughals took the fort.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-102", "question": "Match the land category of Akbar's revenue system with its description: A. Polaj B. Parauti C. Chachar D. Banjar. 1. Land left fallow for five years or more 2. Land left fallow for three or four years 3. Land cultivated every year 4. Land left fallow for a short time to recover its fertility", "options": ["A-3, B-4, C-2, D-1", "A-3, B-2, C-4, D-1", "A-4, B-3, C-2, D-1", "A-3, B-4, C-1, D-2"], "answer": 0, "explanation": "Polaj was cultivated continuously and parauti rested briefly. Chachar lay fallow three or four years and banjar five years or more. Revenue was charged in full on polaj and on parauti when cropped, with concessions on chachar and banjar.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-103", "question": "Match the Mughal local official with the charge: A. Faujdar B. Kotwal C. Amalguzar D. Qanungo. 1. Keeper of land records at the pargana level 2. Revenue collector of a sarkar (district) 3. Police and administration of a town 4. Law and order and military command in a sarkar", "options": ["A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "The faujdar kept order in a sarkar, the kotwal ran a town, the amalguzar collected revenue in a sarkar, and the qanungo kept the land records of a pargana.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-104", "question": "Arrange these events concerning Kandahar in chronological order: 1. Shah Jahan recovers Kandahar through the defection of its Persian governor Ali Mardan Khan 2. Kandahar is lost to Shah Abbas I of Persia 3. Akbar acquires Kandahar 4. Kandahar is finally lost to the Persians", "options": ["3, 2, 1, 4", "2, 3, 1, 4", "3, 1, 2, 4", "3, 2, 4, 1"], "answer": 0, "explanation": "Akbar took Kandahar in 1595, and it was lost to Shah Abbas in 1622 under Jahangir. Shah Jahan regained it in 1638 and lost it for good in 1649; three later sieges failed.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-105", "question": "How many of these were among Aurangzeb's measures? I. He stopped the practice of jharokha darshan. II. He forbade inscribing the kalma on coins. III. He gave up the ceremony of weighing the emperor against gold and silver (tuladan). IV. He banned the celebration of Nauroz.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four were his measures, part of his effort to bring court practice in line with his reading of Islamic law. He also reimposed jizya in 1679 and appointed muhtasibs to enforce public morals.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-106", "question": "Assertion (A): Mewar accepted Mughal suzerainty in 1615 without Rana Amar Singh having to appear in person at the Mughal court. Reason (R): Jahangir excused the Rana from personal attendance, and his son Karan Singh went to court instead.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "After Prince Khurram's campaign, Jahangir offered generous terms: Chittor was returned, the Rana did not have to attend court, and Karan Singh received a mansab. R explains how A came about.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-107", "question": "Match the revolt against Aurangzeb with its leader or region: A. Jat revolt B. Satnami revolt C. Bundela resistance D. Rathor resistance. 1. Durgadas, in Marwar 2. Chhatrasal, in Bundelkhand 3. Narnaul, 1672 4. Gokula, near Mathura, 1669", "options": ["A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1"], "answer": 1, "explanation": "Gokula led the Jats near Mathura in 1669, and the Satnamis rose at Narnaul in 1672. Chhatrasal carved out a Bundela kingdom, and Durgadas Rathor fought for the infant Ajit Singh of Marwar.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-108", "question": "Arrange in chronological order: 1. Fall of the Sayyid brothers 2. Nadir Shah's invasion 3. Farrukhsiyar's farman to the English Company 4. Death of Bahadur Shah I", "options": ["3, 4, 1, 2", "4, 1, 3, 2", "4, 3, 1, 2", "4, 3, 2, 1"], "answer": 2, "explanation": "Bahadur Shah I died in 1712, and Farrukhsiyar granted the farman in 1717. The Sayyid brothers, the king-makers, fell in 1720 under Muhammad Shah, and Nadir Shah sacked Delhi in 1739.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-109", "question": "How many of these statements about Dara Shikoh are correct? I. He wrote the Majma-ul-Bahrain, comparing Sufi and Vedantic ideas. II. He had fifty Upanishads translated into Persian as the Sirr-i-Akbar. III. He was defeated by Aurangzeb and Murad at Samugarh in 1658. IV. He was executed on the orders of Shah Jahan.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Dara was Shah Jahan's favourite son. After his final defeat at Deorai (1659) he was captured and executed on Aurangzeb's orders.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-110", "question": "Match the method of revenue assessment used under the Mughals with its description: A. Zabt B. Ghallabakhshi (batai) C. Nasaq D. Kankut. 1. Sharing the actual produce between the state and the peasant 2. A rough assessment based on the peasant's past payments 3. Measuring the land and applying fixed cash rates for each crop 4. Estimating the yield by inspecting the standing crop", "options": ["A-3, B-1, C-4, D-2", "A-1, B-3, C-2, D-4", "A-3, B-2, C-1, D-4", "A-3, B-1, C-2, D-4"], "answer": 3, "explanation": "Zabt rested on measurement and cash rates (dasturs) and was used in the core provinces. Batai shared the crop. Nasaq was a rough calculation from past receipts, and kankut an estimate of yield made in the field.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-111", "question": "Match the painter with the description: A. Ustad Mansur B. Abul Hasan C. Bishandas D. Daswanth. 1. Given the title Nadir-uz-Zaman by Jahangir 2. Given the title Nadir-ul-Asr; famous for painting birds and animals 3. Sent with Jahangir's embassy to Persia to paint portraits of Shah Abbas 4. A painter of Akbar's workshop who worked on the Razmnama", "options": ["A-2, B-1, C-3, D-4", "A-1, B-2, C-3, D-4", "A-2, B-1, C-4, D-3", "A-2, B-3, C-1, D-4"], "answer": 0, "explanation": "Jahangir gave Mansur the title Nadir-ul-Asr (wonder of the age) and Abul Hasan the title Nadir-uz-Zaman. He sent Bishandas to Persia with his embassy. Daswanth was one of the leading painters of Akbar's Razmnama.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-112", "question": "How many of these statements about Mughal provincial administration are correct? I. In 1580 Akbar divided the empire into twelve subas. II. By the end of his reign Berar, Khandesh and Ahmadnagar had raised the number to fifteen. III. Each suba had a diwan for revenue who reported to the central diwan. IV. A pargana was a larger unit than a sarkar.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV reverses the order: a suba was divided into sarkars, and each sarkar into parganas.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-113", "question": "Assertion (A): Humayun was able to win back his throne in 1555, fifteen years after losing it to Sher Shah. Reason (R): With troops from Shah Tahmasp of Persia he took Kandahar and Kabul, and he then exploited the quarrels among Sher Shah's successors.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Persian help gave Humayun a base in Kandahar and Kabul, and the break-up of the Sur empire after Islam Shah's death (1553) opened the way. He won at Machhiwara and Sirhind in 1555.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-mughal-114", "question": "Sher Shah Suri rebuilt the great road from Sonargaon in Bengal to Peshawar, which later came to be known as the:", "options": ["Silk Road", "Grand Trunk Road", "Uttarapatha", "Dakshinapatha"], "answer": 1, "explanation": "Sher Shah's Sadak-e-Azam, with sarais at regular intervals, later became the Grand Trunk Road. Uttarapatha was the ancient northern trade route.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-mughal-115", "question": "Which Mughal emperor took the title “Alamgir” (conqueror of the world)?", "options": ["Aurangzeb", "Shah Jahan", "Jahangir", "Bahadur Shah I"], "answer": 0, "explanation": "Aurangzeb crowned himself Alamgir in 1658–59. Jahangir means “world-seizer” and was Salim's title.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-mughal-116", "question": "Akbar built Fatehpur Sikri near the hermitage of the Sufi saint:", "options": ["Nizamuddin Auliya", "Moinuddin Chishti", "Bakhtiyar Kaki", "Shaikh Salim Chishti"], "answer": 3, "explanation": "Akbar believed Shaikh Salim Chishti's blessings brought him a son, Salim (Jahangir), and built his new capital at Sikri, where the saint's tomb stands.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-mughal-117", "question": "Under Sher Shah, the document given to each peasant stating the land and the revenue due, and the deed of acceptance signed by the peasant, were called:", "options": ["Patta and qabuliyat", "Farman and nishan", "Dastur and jama", "Zabt and nasaq"], "answer": 0, "explanation": "The patta recorded the state's claim and the qabuliyat was the peasant's acceptance. Akbar continued the practice.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-mughal-118", "question": "Nadir Shah defeated the Mughal army at Karnal and sacked Delhi in 1739 during the reign of:", "options": ["Farrukhsiyar", "Muhammad Shah", "Ahmad Shah", "Alamgir II"], "answer": 1, "explanation": "Muhammad Shah “Rangila” (1719–48) was emperor when Nadir Shah carried off the Peacock Throne and the Kohinoor.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-mughal-119", "question": "Akbar abolished the jizya in:", "options": ["1556", "1575", "1582", "1564"], "answer": 3, "explanation": "Akbar abolished the pilgrim tax in 1563 and the jizya in 1564. Aurangzeb reimposed the jizya in 1679.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-mughal-120", "question": "The Sikh leader Banda Singh Bahadur was captured and executed in Delhi in 1716 during the reign of:", "options": ["Bahadur Shah I", "Jahandar Shah", "Farrukhsiyar", "Muhammad Shah"], "answer": 2, "explanation": "Farrukhsiyar's forces captured Banda at Gurdas Nangal. Banda had earlier set up Sikh rule in Punjab after Guru Gobind Singh's death in 1708.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-mughal-121", "question": "Guru Gobind Singh founded the Khalsa in 1699 at:", "options": ["Amritsar", "Nanded", "Anandpur Sahib", "Kartarpur"], "answer": 2, "explanation": "The Khalsa was created at Anandpur on Baisakhi 1699, during Aurangzeb's reign. Guru Gobind Singh died at Nanded in 1708.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-mughal-122", "question": "The system of “du-aspa sih-aspa” rank, letting selected mansabdars maintain more troopers without a higher zat, was introduced by:", "options": ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], "answer": 1, "explanation": "Jahangir introduced du-aspa sih-aspa (two- and three-horse troopers). Mahabat Khan was among the first to receive it.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-123", "question": "In the Mughal revenue system, “khalisa” land was land whose revenue:", "options": ["Was assigned to mansabdars as jagir", "Went directly to the imperial treasury", "Was granted to scholars and holy men", "Was collected by zamindars for themselves"], "answer": 1, "explanation": "Khalisa was crown land administered directly for the emperor. Jagirs paid mansabdars, and madad-i-maash grants supported scholars and religious men.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-124", "question": "Under the Mughals, “madad-i-maash” grants were:", "options": ["Loans to peasants for seed and cattle", "Rent-free land given to scholars and religious persons", "Salaries paid in cash to mansabdars", "Taxes on trade passing through towns"], "answer": 1, "explanation": "Madad-i-maash (also suyurghal) were revenue-free grants for maintenance of learned and pious persons. Loans to cultivators were called taqavi.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-125", "question": "The first Jesuit mission from Goa, including Rudolf Acquaviva and Antonio Monserrate, reached Akbar's court in:", "options": ["1562", "1572", "1595", "1580"], "answer": 3, "explanation": "The first mission arrived in 1580, soon after the Ibadat Khana debates were opened to all faiths. Monserrate later wrote an account of Akbar's court.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-126", "question": "The English merchant who travelled through India in Akbar's reign and described Agra and Fatehpur Sikri was:", "options": ["Ralph Fitch", "William Hawkins", "Sir Thomas Roe", "Peter Mundy"], "answer": 0, "explanation": "Ralph Fitch travelled in the 1580s. Hawkins and Roe visited Jahangir, and Peter Mundy came in Shah Jahan's reign.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-127", "question": "In the Battle of Saraighat (1671), the Mughal army under Raja Ram Singh was defeated by the Ahom general:", "options": ["Lachit Borphukan", "Gadadhar Singha", "Rudra Singha", "Momai Tamuli"], "answer": 0, "explanation": "Lachit Borphukan's naval victory on the Brahmaputra near Guwahati stopped Mughal expansion into Assam. Gadadhar and Rudra Singha were later Ahom kings.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-128", "question": "Mir Jumla, who led Aurangzeb's invasion of Assam in 1662, had earlier been the chief minister of:", "options": ["Bijapur", "Golconda", "Ahmadnagar", "Bengal"], "answer": 1, "explanation": "Mir Jumla, a Persian diamond merchant, was wazir of Golconda before joining the Mughals; he gave Shah Jahan a famous diamond and later served Aurangzeb as governor of Bengal.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-129", "question": "The English East India Company received permission to set up a permanent factory at Surat in 1613 from:", "options": ["Akbar", "Shah Jahan", "Jahangir", "Aurangzeb"], "answer": 2, "explanation": "Jahangir's farman followed Thomas Best's naval victory over the Portuguese at Swally (1612). Thomas Roe later secured wider privileges.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-130", "question": "Early in his reign Aurangzeb abolished which of these levies?", "options": ["Jizya and the pilgrim tax", "Rahdari (transit dues) and pandari (ground rent)", "Kharaj and ushr", "Zakat and khams"], "answer": 1, "explanation": "Aurangzeb abolished rahdari and pandari, which burdened trade, though officials often kept collecting them. He reimposed, not abolished, the jizya.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-131", "question": "Which Sikh Guru built the Akal Takht at Amritsar and adopted a martial stance against the Mughals?", "options": ["Guru Arjan Dev", "Guru Hargobind", "Guru Har Rai", "Guru Tegh Bahadur"], "answer": 1, "explanation": "Guru Hargobind, son of the martyred Guru Arjan, wore two swords (miri and piri), built the Akal Takht and fought Mughal forces in Shah Jahan's reign.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-mughal-132", "question": "Arrange these annexations of Akbar in chronological order: 1. Kashmir 2. Sindh 3. Malwa 4. Chittor", "options": ["3, 4, 2, 1", "4, 3, 1, 2", "3, 1, 4, 2", "3, 4, 1, 2"], "answer": 3, "explanation": "Malwa (1561), Chittor (1568), Kashmir (1586) and Sindh (1591).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-133", "question": "Match the Mughal emperor with the place of his tomb: A. Babur B. Humayun C. Akbar D. Jahangir — 1. Shahdara, Lahore 2. Kabul 3. Sikandra 4. Delhi", "options": ["A-2, B-4, C-3, D-1", "A-4, B-2, C-3, D-1", "A-2, B-3, C-4, D-1", "A-2, B-4, C-1, D-3"], "answer": 0, "explanation": "Babur lies in the Bagh-e-Babur at Kabul, Humayun in Delhi, Akbar at Sikandra near Agra and Jahangir at Shahdara near Lahore.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-mughal-134", "question": "Consider the following statements: 1. The Moti Masjid inside the Red Fort, Delhi was built by Aurangzeb. 2. The Moti Masjid in the Agra Fort was built by Shah Jahan. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Aurangzeb built the small marble Moti Masjid for his private prayers in the Red Fort; Shah Jahan built the larger one at Agra.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-135", "question": "Assertion (A): Mughal mansabdars did not become a hereditary landed aristocracy. Reason (R): Jagirs were regularly transferred and a mansab was not inherited; a mansabdar's assets could be resumed by the state at his death.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Transfers and escheat kept nobles dependent on the emperor, unlike the hereditary iqtas of Firoz Shah's time.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-136", "question": "Consider the following statements: 1. Sher Shah fixed the state's share at one-third of the average produce, worked out through crop-wise schedules of rates. 2. Raja Todar Mal, who later built Akbar's revenue system, had earlier served under Sher Shah. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Todar Mal worked for Sher Shah (including on Rohtas fort in Punjab) and later shaped Akbar's zabt system.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-137", "question": "How many of these statements about Nur Jahan are correct? I. She built the tomb of her father, Itimad-ud-Daulah, at Agra. II. Coins were struck in her name. III. She was the mother of Shah Jahan. IV. She tried to resist Mahabat Khan's seizure of Jahangir in 1626.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. Shah Jahan (Khurram) was the son of Jahangir's Rajput wife; Nur Jahan's niece, Mumtaz Mahal, was his wife.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-mughal-138", "question": "Arrange in chronological order: 1. Sir Thomas Roe reaches Jahangir's court 2. First Jesuit mission at Akbar's court 3. Jahangir's farman for the English factory at Surat 4. Shah Jahan expels the Portuguese from Hugli", "options": ["2, 1, 3, 4", "2, 3, 4, 1", "2, 3, 1, 4", "3, 2, 1, 4"], "answer": 2, "explanation": "Jesuit mission (1580), Surat farman (1613), Roe at court (1615–19) and Hugli (1632).", "difficulty": "very-hard", "source": "UPSC Prelims"},
];

export default questions;
